// ============================================================
// HireSphere AI — Secure file storage
// Resume PDFs live OUTSIDE the public/ directory and are served
// exclusively through the authorized /api/resumes/[id]/download
// endpoint which performs ownership/role checks on every request.
// ============================================================

import path from 'path';

export const UPLOAD_DIR =
  process.env.UPLOAD_DIR ?? path.join(process.cwd(), 'uploads', 'resumes');

export function resumeFilePath(storedName: string): string {
  // storedName is generated by safeStoredName() — sanitized alnum/._- only
  const clean = path.basename(storedName).replace(/[^a-zA-Z0-9._\-]/g, '');
  return path.join(UPLOAD_DIR, clean);
}
